#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

# Jalan dari root repo, apa pun direktori asalnya.
cd "$(dirname "$0")/.."

# Nama variabel sengaja tidak ada di .env: `ask` menawarkan nilai .env sebagai
# default, dan URL produksi TIDAK PERNAH ditulis ke disk (tanpa write_env).
PROD_DATABASE_URL=""
BACKUP_FILE=""
COPY_DB=""
SCRIPT_PATH=""
MAPPING_FILE=""   # khusus scripts/pemetaan-divisi.ts

# db_label URL → "host/nama_db" tanpa user & password.
db_label() { node -e 'const u=new URL(process.argv[1]); console.log(u.host + u.pathname)' "$1"; }

run_script() { # run_script URL [--apply]
  local url="$1"; shift
  printf '\n'
  DATABASE_URL="$url" npx tsx "$SCRIPT_PATH" ${MAPPING_FILE:+"$MAPPING_FILE"} "$@"
}

banner "Skrip data sekali jalan ke produksi"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Pilih skrip"
say "Skrip sekali jalan yang tersedia:"
for f in scripts/koreksi-sabtu.ts scripts/pemetaan-divisi.ts; do
  [[ -f "$f" ]] && step "$f"
done
note "Kosongkan untuk scripts/koreksi-sabtu.ts."
ask SCRIPT_PATH "Path skrip:"
SCRIPT_PATH="${SCRIPT_PATH:-scripts/koreksi-sabtu.ts}"
if [[ ! -f "$SCRIPT_PATH" ]]; then
  warn "File $SCRIPT_PATH tidak ada."; exit 1
fi
printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$SCRIPT_PATH"
if [[ "$SCRIPT_PATH" == *pemetaan-divisi.ts ]]; then
  say "Skrip ini butuh file pemetaan lokal (userId,email,jabatan) dari snapshot User"
  say "produksi. Format: scripts/pemetaan-divisi.example.csv. Jangan di-commit."
  ask MAPPING_FILE "Path file pemetaan (.csv/.json):"
  MAPPING_FILE="${MAPPING_FILE/#\~/$HOME}"
  if [[ ! -f "$MAPPING_FILE" ]]; then
    warn "File $MAPPING_FILE tidak ada."; exit 1
  fi
  printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$MAPPING_FILE"
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Backup produksi"
say "Backup ini dipakai dua kali: untuk salinan lokal, dan sebagai jalan pulang"
say "kalau --apply ke produksi ternyata salah. Simpan sampai semuanya selesai."
printf '\n'
step "Ambil DATABASE_URL produksi dari .env di server produksi."
note "Bentuknya postgresql://USER:PASSWORD@HOST:5432/NAMA_DB. Tidak disimpan ke disk."
note "Database produksi hanya bisa diakses dari server? Kosongkan, jalankan pg_dump"
note "di server, salin file-nya ke Mac ini (scp), lalu isi path-nya di bawah."
ask_secret PROD_DATABASE_URL "DATABASE_URL produksi (input tersembunyi):"
if [[ -n "$PROD_DATABASE_URL" ]]; then
  BACKUP_FILE="$HOME/Desktop/tam-prod-$(date +%Y-%m-%d-%H%M).dump"
  say "pg_dump $(db_label "$PROD_DATABASE_URL") → $BACKUP_FILE"
  if ! pg_dump --format=custom --no-owner -d "$PROD_DATABASE_URL" -f "$BACKUP_FILE"; then
    rm -f "$BACKUP_FILE"   # pg_dump yang gagal meninggalkan file 0 byte
    warn "pg_dump gagal — tidak ada backup. Periksa URL atau dump dari server."; exit 1
  fi
else
  ask BACKUP_FILE "Path file .dump hasil pg_dump --format=custom:"
  BACKUP_FILE="${BACKUP_FILE/#\~/$HOME}"
fi
# Backup palsu (0 byte / bukan dump aplikasi) berhenti di sini.
if [[ ! -s "$BACKUP_FILE" ]]; then
  warn "$BACKUP_FILE tidak ada atau 0 byte — itu bukan backup."; exit 1
fi
if ! pg_restore --list "$BACKUP_FILE" 2>/dev/null | grep -q 'TABLE DATA public _prisma_migrations'; then
  warn "$BACKUP_FILE tidak terbaca pg_restore atau tidak berisi _prisma_migrations."; exit 1
fi
printf '  %s✓ backup sah%s %s (%s)\n' "$GREEN" "$RESET" "$BACKUP_FILE" "$(du -h "$BACKUP_FILE" | cut -f1)"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Salinan lokal"
note "Kosongkan untuk tam_prod_copy. Isinya akan DIHAPUS lalu diisi ulang dari backup."
ask COPY_DB "Nama database salinan lokal:"
COPY_DB="${COPY_DB:-tam_prod_copy}"
COPY_URL="postgresql://localhost:5432/$COPY_DB"
if psql -d postgres -Atc "SELECT 1 FROM pg_database WHERE datname = '$COPY_DB'" | grep -q 1; then
  confirm "Database lokal $COPY_DB sudah ada. Hapus dan isi ulang dari backup?" || exit 1
fi
dropdb --if-exists "$COPY_DB"
createdb "$COPY_DB"
pg_restore --no-owner --no-privileges -d "$COPY_DB" "$BACKUP_FILE"
printf '  %s✓ restore%s %s\n' "$GREEN" "$RESET" "$COPY_URL"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Dry-run di salinan"
say "Periksa tabelnya: jumlah baris, tabel konflik (kalau ada), dan baris yang"
say "seharusnya TIDAK ikut. Tidak ada yang ditulis."
run_script "$COPY_URL" || { warn "Skrip berhenti — perbaiki penyebabnya dulu."; exit 1; }
printf '\n'
confirm "Hasil dry-run sesuai yang diharapkan?" || exit 1

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Coba --apply di salinan"
say "Gladi bersih: --apply dua kali ke salinan. Yang kedua harus 0 baris."
if confirm "Jalankan --apply ke salinan $COPY_DB?"; then
  run_script "$COPY_URL" --apply || { warn "Apply di salinan gagal."; exit 1; }
  run_script "$COPY_URL" --apply || { warn "Apply kedua di salinan gagal."; exit 1; }
  printf '\n'
  step "Cek hasilnya di aplikasi (terminal lain), lalu buka halaman admin terkait:"
  note "DATABASE_URL=$COPY_URL npm run dev"
  pause "Sudah dicek? Enter untuk lanjut"
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "--apply ke produksi"
if [[ -z "$PROD_DATABASE_URL" ]]; then
  ask_secret PROD_DATABASE_URL "DATABASE_URL produksi (input tersembunyi):"
fi
[[ -n "$PROD_DATABASE_URL" ]] || { note "Dilewati — produksi tidak disentuh."; finish; return; }
PROD_LABEL=$(db_label "$PROD_DATABASE_URL")
say "Dry-run ke produksi dulu ($PROD_LABEL):"
run_script "$PROD_DATABASE_URL" || { warn "Skrip berhenti di produksi — tidak ada yang ditulis."; exit 1; }
printf '\n'
warn "Langkah berikut MENULIS ke produksi. Backup: $BACKUP_FILE"
printf '  %sKetik persis "%s" untuk melanjutkan:%s ' "$YELLOW" "APPLY $PROD_LABEL" "$RESET"
read -r TYPED || true
if [[ "$TYPED" != "APPLY $PROD_LABEL" ]]; then
  note "Tidak cocok — produksi tidak disentuh."; exit 1
fi
run_script "$PROD_DATABASE_URL" --apply || { warn "Apply ke produksi gagal (transaksi dibatalkan)."; exit 1; }
say "Cek ulang: dry-run sesudah apply harus 0 baris sasaran."
run_script "$PROD_DATABASE_URL" || true
pause

finish
note "Backup produksi: $BACKUP_FILE — simpan sampai hasilnya dicek di aplikasi."
}

run_wizard "$@"; exit
